"use client";

import { useState } from "react";
import {
    History,
    FileText,
    Plus,
    X,
    Search,
    Upload,
    ChevronDown,
    Save,
    Pill,
    Loader2,
    CheckCircle2,
    ScanLine,
    Calendar,
    Package,
    ArrowRight
} from "lucide-react";
import { useData } from "@/lib/hooks";
import ExpiryScanner from "@/components/expiry/ExpiryScanner";

export default function PurchasesPage() {
    const [showForm, setShowForm] = useState(false);
    const [isScanning, setIsScanning] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [showScanner, setShowScanner] = useState(false);
    const [currentScanIdx, setCurrentScanIdx] = useState<number | null>(null);

    const { data: suppliers } = useData<any[]>("/api/suppliers");
    const { data: products } = useData<any[]>("/api/products");
    const { data: purchaseHistory, refetch: refetchHistory } = useData<any[]>("/api/purchases");

    const [formItems, setFormItems] = useState<any[]>([]);

    const handleSavePurchase = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsSubmitting(true);
        const formData = new FormData(e.currentTarget);
        const data = {
            supplierId: formData.get("supplierId"),
            invoiceNo: formData.get("invoiceNo"),
            date: formData.get("date"),
            items: formItems
        };

        setTimeout(() => {
            console.log("Mock saved purchase:", data);
            setShowForm(false);
            setFormItems([]);
            refetchHistory();
            setIsSubmitting(false);
            alert("Purchase order successfully recorded!");
        }, 800);
    };

    const addItem = () => {
        setFormItems([...formItems, { productId: "", batchNo: "", expiryDate: "", quantity: 1, purchasePrice: 0 }]);
    };

    const removeItem = (idx: number) => {
        setFormItems(formItems.filter((_, i) => i !== idx));
    };

    const handleScanComplete = (data: any) => {
        if (Array.isArray(data)) {
            // Bulk add to form items
            const newReceiptItems = data.map(item => ({
                id: Math.random().toString(36).substr(2, 9),
                productId: products?.find((p: any) =>
                    p.name.toLowerCase().includes(item.productName.toLowerCase()) ||
                    item.productName.toLowerCase().includes(p.name.toLowerCase())
                )?.id || "",
                batchNo: item.batchNo || "",
                mfgDate: item.mfgDate || "",
                expiryDate: item.expiryDate || "",
                quantity: 1,
                purchasePrice: 0,
                scannedName: item.productName // Keep original for reference if product match fails
            }));

            // If we were scanning for a specific row, replace it, otherwise append
            if (currentScanIdx !== null) {
                const updatedItems = [...formItems];
                updatedItems.splice(currentScanIdx, 1, ...newReceiptItems);
                setFormItems(updatedItems);
            } else {
                setFormItems([...formItems, ...newReceiptItems]);
            }
        } else if (currentScanIdx !== null) {
            const newItems = [...formItems];
            newItems[currentScanIdx].batchNo = data.batchNo || "";
            newItems[currentScanIdx].mfgDate = data.mfgDate || "";
            newItems[currentScanIdx].expiryDate = data.expiryDate || "";
            setFormItems(newItems);
        }
        setShowScanner(false);
        setCurrentScanIdx(null);
    };

    return (
        <>
            <div className="flex flex-col gap-8 animate-fade-in-up">
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-3xl font-black text-gray-900 uppercase tracking-tight">IR Procurement</h1>
                        <p className="text-gray-500 mt-1 font-medium">Record new inventory shipments and track purchase history.</p>
                    </div>
                    <button
                        onClick={() => {
                            setShowForm(true);
                            if (formItems.length === 0) addItem();
                        }}
                        className="btn-primary flex items-center gap-2"
                    >
                        <Plus className="h-4 w-4" />
                        New Purchase Record
                    </button>
                </div>

                {/* Purchase History */}
                <div className="card-premium rounded-3xl overflow-hidden border-0 shadow-2xl shadow-purple-100/50">
                    <div className="p-6 bg-gradient-to-r from-purple-600 to-blue-600 flex items-center justify-between">
                        <div className="flex items-center gap-2 text-white">
                            <History className="h-5 w-5" />
                            <h3 className="text-lg font-bold uppercase tracking-tight">Recent Purchases</h3>
                        </div>
                        <div className="relative w-64">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-white/50" />
                            <input
                                type="text"
                                placeholder="Search invoices..."
                                className="w-full bg-white/10 border border-white/20 rounded-xl py-2 pl-10 pr-4 text-sm text-white placeholder:text-white/50 focus:bg-white/20 transition-all outline-none"
                            />
                        </div>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead>
                                <tr className="bg-gray-50/50 border-b border-gray-100">
                                    <th className="py-4 px-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Invoice #</th>
                                    <th className="py-4 px-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Supplier</th>
                                    <th className="py-4 px-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Date</th>
                                    <th className="py-4 px-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Items</th>
                                    <th className="py-4 px-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Value</th>
                                    <th className="py-4 px-6 text-[10px] font-black text-gray-400 uppercase tracking-widest text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-50">
                                {purchaseHistory?.map((p: any) => (
                                    <tr key={p.id} className="hover:bg-purple-50/30 transition-colors group">
                                        <td className="py-4 px-6 font-black text-gray-900">{p.invoiceNo}</td>
                                        <td className="py-4 px-6">
                                            <div className="flex items-center gap-2">
                                                <div className="w-8 h-8 rounded-lg bg-gray-100 flex items-center justify-center font-bold text-gray-500 text-xs uppercase">
                                                    {p.supplier.name.charAt(0)}
                                                </div>
                                                <span className="font-semibold text-gray-700">{p.supplier.name}</span>
                                            </div>
                                        </td>
                                        <td className="py-4 px-6 text-sm text-gray-500 font-medium">{new Date(p.date).toLocaleDateString()}</td>
                                        <td className="py-4 px-6">
                                            <span className="bg-blue-50 text-blue-600 px-2.5 py-1 rounded-lg text-xs font-black">
                                                {p.items.length} MEDICINES
                                            </span>
                                        </td>
                                        <td className="py-4 px-6 font-black text-purple-600">PKR {p.total.toLocaleString()}</td>
                                        <td className="py-4 px-6 text-right">
                                            <button className="p-2 hover:bg-white rounded-xl shadow-sm border border-gray-100 text-gray-400 hover:text-purple-600 transition-all">
                                                <ArrowRight className="h-4 w-4" />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                                {(!purchaseHistory || purchaseHistory.length === 0) && (
                                    <tr>
                                        <td colSpan={6} className="py-20 text-center">
                                            <div className="flex flex-col items-center gap-3 opacity-20">
                                                <Package className="h-16 w-16" />
                                                <p className="font-black uppercase tracking-widest">No Procurement Records</p>
                                            </div>
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            <PurchaseModal
                showForm={showForm}
                setShowForm={setShowForm}
                handleSavePurchase={handleSavePurchase}
                suppliers={suppliers}
                products={products}
                formItems={formItems}
                setFormItems={setFormItems}
                addItem={addItem}
                removeItem={removeItem}
                isSubmitting={isSubmitting}
                onScanItem={(idx: number) => {
                    setCurrentScanIdx(idx);
                    setShowScanner(true);
                }}
            />

            {showScanner && (
                <ExpiryScanner
                    onClose={() => setShowScanner(false)}
                    onScanComplete={handleScanComplete}
                />
            )}
        </>
    );
}

function PurchaseModal({
    showForm,
    setShowForm,
    handleSavePurchase,
    suppliers,
    products,
    formItems,
    setFormItems,
    addItem,
    removeItem,
    isSubmitting,
    onScanItem
}: any) {
    return (
        <>
            {showForm && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[100] flex items-center justify-center p-4 overflow-y-auto">
                    <div className="bg-white rounded-[2rem] w-full max-w-5xl max-h-[90vh] overflow-y-auto animate-fade-in-up shadow-2xl relative border border-white/20">
                        <div className="p-8 border-b border-gray-100 flex items-center justify-between sticky top-0 bg-white/80 backdrop-blur-xl z-10 transition-all">
                            <div>
                                <h2 className="text-2xl font-black text-gray-900 uppercase tracking-tight">New Stock Receipt</h2>
                                <p className="text-gray-500 font-medium text-sm">Enter shipment details from invoice.</p>
                            </div>
                            <button onClick={() => setShowForm(false)} className="p-3 hover:bg-red-50 hover:text-red-500 rounded-2xl transition-all">
                                <X className="h-6 w-6" />
                            </button>
                        </div>

                        <form onSubmit={handleSavePurchase} className="p-8">
                            <div className="grid md:grid-cols-3 gap-8 mb-10">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-purple-600 uppercase tracking-widest flex items-center gap-2">
                                        <Package className="h-3 w-3" /> Supplier Entity
                                    </label>
                                    <select name="supplierId" required className="w-full h-14 bg-gray-50 border-gray-100 rounded-2xl px-5 text-sm font-bold focus:ring-4 focus:ring-purple-500/10 transition-all">
                                        <option value="">Choose Supplier</option>
                                        {suppliers?.map((s: any) => <option key={s.id} value={s.id}>{s.name}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-purple-600 uppercase tracking-widest flex items-center gap-2">
                                        <FileText className="h-3 w-3" /> Invoice Reference
                                    </label>
                                    <input name="invoiceNo" required placeholder="e.g. INV-2024-001" className="w-full h-14 bg-gray-50 border-gray-100 rounded-2xl px-5 text-sm font-bold focus:ring-4 focus:ring-purple-500/10 transition-all" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-purple-600 uppercase tracking-widest flex items-center gap-2">
                                        <Calendar className="h-3 w-3" /> Shipment Date
                                    </label>
                                    <input name="date" type="date" required className="w-full h-14 bg-gray-50 border-gray-100 rounded-2xl px-5 text-sm font-bold focus:ring-4 focus:ring-purple-500/10 transition-all" defaultValue={new Date().toISOString().split('T')[0]} />
                                </div>
                            </div>

                            <div className="space-y-4 mb-10">
                                <div className="flex items-center justify-between px-2">
                                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Inventory Line Items</h3>
                                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Items: {formItems.length}</span>
                                </div>

                                <div className="space-y-3">
                                    {formItems.map((item: any, idx: number) => (
                                        <div key={idx} className="bg-gray-50/50 p-5 rounded-3xl border border-gray-100 grid md:grid-cols-12 gap-3 items-end animate-fade-in group">
                                            <div className="md:col-span-3 space-y-2">
                                                <label className="text-[10px] font-black text-gray-400 uppercase">Medicine Name</label>
                                                <select
                                                    value={item.productId}
                                                    onChange={(e) => {
                                                        const newItems = [...formItems];
                                                        newItems[idx].productId = e.target.value;
                                                        setFormItems(newItems);
                                                    }}
                                                    className="w-full h-12 bg-white border border-gray-200 rounded-xl px-4 text-xs font-bold"
                                                >
                                                    <option value="">Select Medicine</option>
                                                    {products?.map((p: any) => <option key={p.id} value={p.id}>{p.name}</option>)}
                                                </select>
                                            </div>
                                            <div className="md:col-span-2 space-y-2">
                                                <label className="text-[10px] font-black text-gray-400 uppercase">Batch No</label>
                                                <div className="relative">
                                                    <input
                                                        value={item.batchNo}
                                                        onChange={(e) => { const n = [...formItems]; n[idx].batchNo = e.target.value; setFormItems(n); }}
                                                        placeholder="Batch"
                                                        className="w-full h-12 bg-white border border-gray-200 rounded-xl px-4 text-xs font-bold pr-10"
                                                    />
                                                    <button
                                                        type="button"
                                                        onClick={() => onScanItem(idx)}
                                                        className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 hover:bg-purple-50 text-purple-600 rounded-lg transition-all"
                                                    >
                                                        <ScanLine className="h-4 w-4" />
                                                    </button>
                                                </div>
                                            </div>
                                            <div className="md:col-span-2 space-y-2">
                                                <label className="text-[10px] font-black text-gray-400 uppercase">MFG Date</label>
                                                <input type="date" value={item.mfgDate} onChange={(e) => { const n = [...formItems]; n[idx].mfgDate = e.target.value; setFormItems(n); }} className="w-full h-12 bg-white border border-gray-200 rounded-xl px-4 text-xs font-bold" />
                                            </div>
                                            <div className="md:col-span-2 space-y-2">
                                                <label className="text-[10px] font-black text-gray-400 uppercase">Expiry Date</label>
                                                <input type="date" value={item.expiryDate} onChange={(e) => { const n = [...formItems]; n[idx].expiryDate = e.target.value; setFormItems(n); }} className="w-full h-12 bg-white border border-gray-200 rounded-xl px-4 text-xs font-bold" />
                                            </div>
                                            <div className="md:col-span-1 space-y-2">
                                                <label className="text-[10px] font-black text-gray-400 uppercase">Strips</label>
                                                <input type="number" value={item.quantity} onChange={(e) => { const n = [...formItems]; n[idx].quantity = e.target.value; setFormItems(n); }} className="w-full h-12 bg-white border border-gray-200 rounded-xl px-4 text-xs font-bold" />
                                            </div>
                                            <div className="md:col-span-1 space-y-2">
                                                <label className="text-[10px] font-black text-gray-400 uppercase">Price</label>
                                                <input type="number" value={item.purchasePrice} onChange={(e) => { const n = [...formItems]; n[idx].purchasePrice = e.target.value; setFormItems(n); }} className="w-full h-12 bg-white border border-gray-200 rounded-xl px-4 text-xs font-bold" />
                                            </div>
                                            <div className="md:col-span-1 flex justify-center">
                                                <button
                                                    type="button"
                                                    onClick={() => removeItem(idx)}
                                                    className="p-3 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                                                >
                                                    <X className="h-5 w-5" />
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>

                                <button type="button" onClick={addItem} className="group w-full py-5 border-2 border-dashed border-gray-200 rounded-[2rem] text-gray-400 font-black uppercase text-xs tracking-widest hover:border-purple-300 hover:text-purple-600 hover:bg-purple-50/30 transition-all flex items-center justify-center gap-2">
                                    <Plus className="h-4 w-4 group-hover:scale-125 transition-transform" />
                                    Append Medicine Line
                                </button>
                            </div>

                            <div className="flex gap-4">
                                <button type="button" onClick={() => setShowForm(false)} className="flex-1 py-5 rounded-3xl border border-gray-100 text-gray-500 font-black uppercase tracking-widest hover:bg-gray-50 transition-all">Cancel</button>
                                <button disabled={isSubmitting} type="submit" className="flex-2 py-5 bg-gradient-to-r from-purple-600 to-blue-600 text-white rounded-3xl font-black uppercase tracking-widest shadow-2xl shadow-purple-200 hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-50">
                                    {isSubmitting ? <Loader2 className="h-6 w-6 animate-spin mx-auto" /> : "Authorize Stock Deposit"}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </>
    );
}
